import type { SQLiteDatabase } from 'expo-sqlite';

import { useExamStore, useProfileStore, useTopicStore } from '@/store';

/**
 * Every table that holds rows generated by the user on this device, listed in
 * the order they are cleared. `practice_exam_results` (the child) is deleted
 * before `practice_exams` (its parent) so the reset never has to rely on the
 * foreign-key cascade. `user_profile` and `app_settings` are singletons;
 * clearing them removes the profile and the saved theme preference.
 */
export const USER_DATA_TABLES = [
  'practice_exam_results',
  'practice_exams',
  'topic_progress',
  'user_profile',
  'app_settings',
] as const;

export type UserDataTable = (typeof USER_DATA_TABLES)[number];

/**
 * Deletes every user-generated row in one transaction.
 *
 * The complete deletion and the "tables are empty" verification run inside a
 * single `withTransactionAsync`, so any failure rolls the whole operation back
 * and no table is left half-cleared. Tables are never dropped, renamed or
 * recreated, the schema version is not touched, and the archived legacy tables
 * and static curriculum data are never referenced.
 */
export async function clearLocalUserData(db: SQLiteDatabase): Promise<void> {
  await db.withTransactionAsync(async () => {
    for (const table of USER_DATA_TABLES) {
      await db.runAsync(`DELETE FROM ${table};`);
    }

    // Commit only once every table is verifiably empty; a mismatch rolls back.
    for (const table of USER_DATA_TABLES) {
      const row = await db.getFirstAsync<{ count: number }>(
        `SELECT COUNT(*) AS count FROM ${table};`,
      );

      if ((row?.count ?? 0) !== 0) {
        throw new Error(`Yerel veri temizliği doğrulanamadı: "${table}" boş değil.`);
      }
    }
  });
}

export type ResetLocalUserDataOptions = {
  /** The single application connection, or `null` while it is unavailable. */
  db: SQLiteDatabase | null;
  /**
   * Resets the in-memory theme preference to `system` without writing a
   * replacement settings row.
   */
  resetThemePreference: () => void;
  /**
   * Optional safe replacement, run only after the transaction committed and
   * every store was cleared. The root route guard already removes the
   * protected screens when `profileStore` is cleared, so this is a defensive
   * fallback for the case where the active route is not left immediately.
   *
   * A navigation error is logged in development and swallowed: the data was
   * already deleted successfully, so it must never be reported as a deletion
   * failure.
   */
  navigateToOnboarding?: () => void;
};

/**
 * Runs the SQLite reset and only then clears the in-memory Zustand stores.
 *
 * Ordering is the contract: the stores are cleared strictly after the
 * transaction has committed, so a failed reset leaves the database and every
 * store exactly as they were. Clearing `profileStore` flips
 * `onboardingCompleted` to `false`, which is what returns the user to
 * onboarding through the existing protected navigation; the optional
 * `navigateToOnboarding` callback is only a safe fallback for that transition.
 */
export async function resetLocalUserData({
  db,
  resetThemePreference,
  navigateToOnboarding,
}: ResetLocalUserDataOptions): Promise<void> {
  if (db === null) {
    throw new Error('Yerel veriler silinemedi: veritabanına erişilemiyor.');
  }

  await clearLocalUserData(db);

  // SQLite committed: only now may the in-memory state be cleared.
  useExamStore.getState().clearExams();
  useTopicStore.getState().clearProgress();
  useProfileStore.getState().clearProfile();
  resetThemePreference();

  if (navigateToOnboarding !== undefined) {
    try {
      navigateToOnboarding();
    } catch (cause) {
      // Handled separately from the reset: the deletion already succeeded.
      if (__DEV__) {
        console.error('[ClearLocalData] Navigation failed', cause);
      }
    }
  }
}

export type ClearLocalDataRunner = {
  /** True while a reset is in flight. */
  isRunning: () => boolean;
  /**
   * Runs at most one reset at a time; a duplicate call made while a reset is
   * running is ignored instead of starting a competing transaction.
   *
   * The connection and the theme reset are supplied per call rather than
   * captured at creation, so the runner never holds a stale value and can be
   * created once without reading anything during render.
   */
  run: (options: ResetLocalUserDataOptions) => Promise<void>;
};

/**
 * Single-flight wrapper around `resetLocalUserData`, so a double tap can never
 * issue two resets.
 */
export function createClearLocalDataRunner(): ClearLocalDataRunner {
  let running = false;

  return {
    isRunning: () => running,
    run: async (options) => {
      if (running) {
        return;
      }

      running = true;

      try {
        await resetLocalUserData(options);
      } finally {
        running = false;
      }
    },
  };
}
